        </Flex>
      </Container>
    </ThemeProvider>
  );
}

function TabButtonLike({
  id,
  selected,
  onClick,
  children,
}: {
  id: string;
  selected: boolean;
  onClick: () => void;
  children: React.ReactNode;
}) {
  return (
    <Button
      view={selected ? 'action' : 'flat-secondary'}
      onClick={onClick}
      style={{ fontWeight: selected ? 600 : 400 }}
    >
      {children}
    </Button>
  );
}
